Here is my thorough exploration of the project.

---

## 1. Express Server Structure (`src/server/index.js`)

**Full content** (43 lines):

```js
const express = require('express');
const http = require('http');
const path = require("path");
require("dotenv").config({
    path: path.resolve(__dirname, "../../.env"),
});
const { attachChatServer } = require('./chatserver.cjs');
const { attachFaceServer } = require('./modules/facial_recog/facialrecogserver.js');

const app = express();
const server = http.createServer(app);
const port = process.env.PORT || 3001;

attachChatServer(server);
attachFaceServer(app);

app.get('/', (req, res) => {
    res.send('server is running');
});

async function start() {
    try {
        const { startPythonServer, stopPythonServer } = await import('./modules/facial_recog/facenetClient.js');
        await startPythonServer();
        console.log('[FaceNet] Server is ready at http://127.0.0.1:8000');

        const cleanup = () => {
            stopPythonServer();
            process.exit();
        };
        process.on('SIGINT', cleanup);
        process.on('SIGTERM', cleanup);
    } catch (err) {
        console.error('[FaceNet] Failed to start Python server:', err.message);
    }

    server.listen(port, () => {
        console.log(`Listening on port ${port}`);
    });
}

start();
```

**Key observations:**
- Uses **CommonJS (`require`)** for the Express app but uses **dynamic `import()`** for the ESM `facenetClient.js` module.
- Express 5 is used.
- Middleware: only `express.json()` (applied inside `attachFaceServer`).
- No CORS middleware, no static file serving, no cookie parser, no compression.
- Two "attach" functions compose the application: `attachChatServer(server)` and `attachFaceServer(app)`.
- On startup, it spawns a Python FastAPI subprocess running on port 8000 for Facenet inference.
- The chat server is WebSocket-based (using the `websocket` npm package).
- The face server is Express REST (mounted via an Express Router).

---

## 2. Route Files in `src/server/`

### `chatserver.cjs` (WebSocket-based chat)

- Uses `websocket` package (not `ws` or `socket.io`).
- `attachChatServer(server)` accepts the raw `http.Server` instance.
- Accepts all origins (`autoAcceptConnections: false` but `request.accept(null, request.origin)`).
- On connection: sends chat history from PostgreSQL via `readchathistory()`.
- On message: validates `text` (<=1000 chars) and `senderId`, persists via `addmessage()` from `dbcrudmethods.js`, then broadcasts to all connected clients.
- Connection lifecycle tracked in a `Set`.

### `facialrecogserver.js` (Express REST for face operations)

**Full content** (80 lines):

```js
const express = require('express');
const { User, FaceEmbeddings } = require('../../database/dbcrudmethods');

const router = express.Router();

router.post('/api/user/:id/face', async (req, res) => {
    const { id } = req.params;
    const { image } = req.body;
    if (!image || typeof image !== 'string') {
        return res.status(400).json({ error: 'Missing or invalid image base64 in request body' });
    }
    const user = await User.read(id);
    if (!user) {
        return res.status(404).json({ error: 'User not found' });
    }
    const imageData = Buffer.from(image, 'base64');
    const records = await FaceEmbeddings.createFromImage(id, imageData, 'cache');
    res.status(201).json(records.map(r => ({
        imageHash: r.imageHash,
        embeddings: r.embeddings,
        model: r.model,
    })));
});

router.patch('/api/user/:id/face/default', async (req, res) => {
    const { id } = req.params;
    const { image } = req.body;
    if (!image || typeof image !== 'string') {
        return res.status(400).json({ error: 'Missing or invalid image base64 in request body' });
    }
    const user = await User.read(id);
    if (!user) {
        return res.status(404).json({ error: 'User not found' });
    }
    await FaceEmbeddings.deleteByUserIdAndType(id, 'primary');
    const imageData = Buffer.from(image, 'base64');
    const records = await FaceEmbeddings.createFromImage(id, imageData, 'primary');
    res.status(200).json(records.map(r => ({
        imageHash: r.imageHash,
        embeddings: r.embeddings,
        model: r.model,
    })));
});

router.get('/api/user/:id/face/default', async (req, res) => {
    const { id } = req.params;
    const user = await User.read(id);
    if (!user) {
        return res.status(404).json({ error: 'User not found' });
    }
    const faces = await FaceEmbeddings.findPrimaryByUserId(id);
    if (!faces.length) {
        return res.status(404).json({ error: 'No default face found for this user' });
    }
    res.status(200).json(faces.map(r => ({
        imageHash: r.imageHash,
        imageData: r.imageData.toString('base64'),
        embeddings: r.embeddings,
        model: r.model,
    })));
});

function attachFaceServer(app) {
    app.use(express.json());
    app.use(router);
}

module.exports = { attachFaceServer };
```

---

## 3. All Existing API Endpoints

### HTTP endpoints (Express):

| Method | Path | Description | Source |
|--------|------|-------------|--------|
| `GET` | `/` | Health check ("server is running") | `index.js:17` |
| `POST` | `/api/user/:id/face` | Upload a face image (base64 in body) as a **cache** face for a user | `facialrecogserver.js:6` |
| `PATCH` | `/api/user/:id/face/default` | Set/replace the **primary (default)** face for a user (deletes old primary first) | `facialrecogserver.js:29` |
| `GET` | `/api/user/:id/face/default` | Get the primary face embedding + image data for a user | `facialrecogserver.js:54` |

### Python FastAPI endpoints (port 8000, internal -- not exposed to client):

| Method | Path | Description | Source |
|--------|------|-------------|--------|
| `POST` | `/embed` | Get a single Facenet embedding from an image | `python_server/server.py:14` |
| `POST` | `/detect` | Detect face bounding boxes in an image | `python_server/server.py:36` |
| `POST` | `/embed-all` | Detect all faces and get embeddings + cropped face images (base64) | `python_server/server.py:61` |

### WebSocket:

| Type | Description | Source |
|------|-------------|--------|
| Connection | Sends `{type: 'history', messages: [...]}` with chat history | `chatserver.cjs:34-39` |
| Message (inbound) | Receives `{text, senderId, timestamp}`, saves to DB, broadcasts `{type: 'message', message: {...}}` | `chatserver.cjs:46-83` |

---

## 4. `facial_recog` Module Folder Structure

```
src/server/modules/facial_recog/
  facenetClient.js          -- ESM module: startPythonServer(), getFaceEmbedding(), detectFaces(), getFaceEmbeddings()
  facialrecogserver.js      -- CommonJS module: Express router with face CRUD routes + attachFaceServer()
  startFaceNet.js           -- Standalone entry point that just calls startPythonServer()
  test-images/
    dwayne/
      default.png
      img.png
      img_1.png
    reynolds/
      default.png
      img_1.png
      img_2.png
    zendaya/
      default.png
      img.png
      img_1.png
```

**Key files explained:**

- **`facenetClient.js`** (ESM): Spawns the Python server as a child process. Exports:
  - `startPythonServer()` -- installs deps if needed, starts uvicorn, waits for "model loaded" signal.
  - `stopPythonServer()` -- kills the child process.
  - `getFaceEmbedding(imageInput)` -- sends image to `/embed`, returns a 128-d vector.
  - `detectFaces(imageInput)` -- sends image to `/detect`, returns bounding boxes `[{x,y,w,h}]`.
  - `getFaceEmbeddings(imageInput)` -- sends image to `/embed-all`, returns `[{faceImage: Buffer, embedding, bbox}]`.

- **`facialrecogserver.js`** (CommonJS): Express router with 3 face CRUD endpoints (described above). Uses `User` and `FaceEmbeddings` from `dbcrudmethods.js`.

- **`startFaceNet.js`** (ESM): Simple CLI entry point (`npm run dev` runs this) that just starts the Python server.

---

## 5. Client-Side API / Communication Patterns

### Immediate observations:
- **The client does NOT use `fetch`, `axios`, or any HTTP client library** for REST API calls.
- The client currently only communicates with the server via **WebSocket** (chat feature).
- There is **no API utility module** in `src/client/src/`.

### WebSocket communication (`Chat.jsx`):
```js
const CHAT_SERVER_URL = import.meta.env.VITE_CHAT_SERVER_URL || 'ws://localhost:3001';
// ...
const socket = new WebSocket(CHAT_SERVER_URL);
socket.onopen = () => { setIsConnected(true); };
socket.onmessage = (e) => {
    const payload = JSON.parse(e.data);
    if (payload.type === 'history') setMessages(payload.messages);
    if (payload.type === 'message') setMessages((current) => [...current, payload.message]);
    if (payload.type === 'error') console.error(payload.text);
};
// Sending:
socketRef.current.send(JSON.stringify({ text, timestamp, senderId }));
```

### Vite proxy configuration:
```js
// vite.config.js
server: {
    proxy: {
        '/api': 'http://localhost:3001',   // proxies /api/* to Express on port 3001
    },
},
```
This means that if the client ever makes a `fetch('/api/...')` call, it will be proxied to the Express backend. Currently no client code does this.

### Face detection on the client side:
- `Camera.jsx` uses `face-api.js` (loaded via a CDN `<script>` tag in `index.html`) to perform **client-side** face detection using `ssdMobilenetv1`.
- It does NOT send images to the backend for detection.

---

## 6. Image Handling / Upload Patterns

### Backend image flow:
1. **Client-side** (planned but not implemented yet): The `POST` and `PATCH` endpoints accept `image` as a **base64 string** in the request body.
2. **Server-side processing**:
   - `Buffer.from(image, 'base64')` converts the base64 string to a Buffer.
   - `FaceEmbeddings.createFromImage(userId, imageData, imageType)` is called.
   - This imports `getFaceEmbeddings` from `facenetClient.js`, which sends the image buffer to the Python FastAPI server as a multipart form upload (`FormData` with a `Blob`).
   - The Python server receives it via `UploadFile`, decodes with OpenCV, runs DeepFace, returns embeddings and cropped face images (base64).
   - The face images + embeddings are stored in the **PostgreSQL `faceEmbeddings` table** as BLOBs.

### `FaceEmbeddings.createFromImage()` (in `dbcrudmethods.js`):
```js
static async createFromImage(userId, imageData, imageType) {
    const { getFaceEmbeddings } = await import('../modules/facial_recog/facenetClient.js');
    const faces = await getFaceEmbeddings(imageData);
    const results = [];
    for (const face of faces) {
        const imageHash = crypto.createHash('sha256').update(face.faceImage).digest('hex');
        const record = await FaceEmbeddings.create(
            imageHash, userId, imageType,
            face.faceImage,           // Buffer of the cropped face
            JSON.stringify(face.embedding),
            'facenet'
        );
        results.push(record);
    }
    return results;
}
```

### Database schema for images (`db.cjs`):
```js
const faceEmbeddings = sequelize.define("faceEmbeddings", {
    imageHash:  { type: DataTypes.STRING, primaryKey: true },
    userId:     { type: DataTypes.UUID, allowNull: false, references: { model: user, key: "id" } },
    imageType:  { type: DataTypes.STRING, allowNull: false },  // 'primary' or 'cache'
    imageData:  { type: DataTypes.BLOB("long"), allowNull: false },
    embeddings: { type: DataTypes.STRING, allowNull: false },
    model:      { type: DataTypes.STRING, allowNull: false },
});
```

---

## 7. Database Layer

**`database/db.cjs`** -- Sequelize setup with 5 models:
- `users` (id UUID, enName, zhName)
- `messages` (content, timestamp, senderId FK to users)
- `attendee` (name)
- `admin` (name, privileges)
- `faceEmbeddings` (imageHash PK, userId FK, imageType, imageData BLOB, embeddings JSON string, model)

**`database/dbcrudmethods.js`** -- CRUD classes:
- `Model` -- abstract base
- `User` -- wraps `users` table; `create(enName, zhName)`, `read(id)`, `update()`, `delete()`
- `FaceEmbeddings` -- wraps `faceEmbeddings` table; `create()`, `read(imageHash)`, `update()`, `delete()`, plus:
  - `findPrimaryByUserId(userId)` -- finds all 'primary' imageType records for a user
  - `deleteByUserIdAndType(userId, imageType)` -- bulk delete
  - `createFromImage(userId, imageData, imageType)` -- the high-level method that calls the Python server

---

## 8. Test Files

**`tests/seed.js`**:
- Reads person folders from `tests/modules/facial_recog/test-images/` (note: the actual test images are at `src/server/modules/facial_recog/test-images/`, but the seed script looks at a different path `tests/modules/facial_recog/test-images/` which does not exist -- this appears to be a bug).
- For each person, reads a `default.*` image, creates a `User`, then calls `FaceEmbeddings.createFromImage()` to register primary face embeddings.
- Also finds additional test images for each person.

**`tests/test-endpoints.js`**:
- Tests the three Python FastAPI endpoints (`/embed`, `/detect`, `/embed-all`) directly by sending a test image via `fetch` + `FormData`.

---

## Summary of Architecture

```
Client (React + Vite)           Server (Express + WS)           Python (FastAPI)
       |                              |                              |
[Browser]                       [Node.js port 3001]            [Python port 8000]
       |                              |                              |
  Chat.jsx ---WebSocket---> chatserver.cjs                          |
  Camera.jsx (face-api.js           |                              |
    client-side detection)          |                              |
       |                       facialrecogserver.js                |
       |                       POST/PATCH/GET /api/user/:id/face   |
       |                              |                              |
       |                       facenetClient.js ---HTTP POST---> server.py
       |                                                            |
       |                       PostgreSQL <--> db.cjs               |
       |                                   (Sequelize)              |
```

**Key gaps / notes:**
- No client code currently calls the face REST endpoints -- they exist on the server but have no client-side consumers yet.
- The `Camera.jsx` component does all face detection client-side with `face-api.js` and does not integrate with the backend.
- The `tests/seed.js` script references a test images path that does not match the actual location of the test images.
- No file upload middleware (like `multer`) is used -- images are sent as base64 strings in JSON bodies.
